```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn x1(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let guard_a = a.lock().unwrap();
    let guard_b = b.lock().unwrap();
    drop(guard_b);
    drop(guard_a);
}

fn x2(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let guard_a = a.lock().unwrap();
    let guard_b = b.lock().unwrap();
    drop(guard_b);
    drop(guard_a);
}

fn outer(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let handle_x1 = thread::spawn(move || x1(a1, b1));

    let handle_x2 = thread::spawn(move || x2(a, b));

    handle_x1.join().unwrap();
    handle_x2.join().unwrap();
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let handle_outer = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        thread::spawn(move || outer(a, b))
    };

    handle_outer.join().unwrap();
    println!("DONE done=1");
}
